descriptor.controllerScript:
self.onInit = function () {
    var MODE = 'led';              // 'led' = customer version, 'value' = admin version
    var COUNT = 7;
    var NAME = 'Reaktor';
    var SUBTITLE = 'hőmérséklet';
    var KEY = 't';                 // keys t1 ... t7
    var UNIT = ' °C';
    var DIVISOR = 1;               // set to 10 if the telemetry is in tenths of a degree
    var MIN = 0, MAX = 500;        // LED turns red outside this range (same unit as the telemetry)

    var COL_W = 88, DESIGN_W = COL_W * COUNT, DESIGN_H = 104;
    var INK = '#1b1f3b';

    var root = self.ctx.$container[0].querySelector('.rs-root');
    var stage = root.querySelector('.rs-stage');
    var cells = [];
    var ro = null;

    stage.style.width = DESIGN_W + 'px';
    stage.style.height = DESIGN_H + 'px';
    stage.style.display = 'flex';
    stage.style.fontFamily = 'inherit';
    stage.style.color = INK;

    function el(tag, css, text) {
        var e = document.createElement(tag);
        if (css) { e.style.cssText = css; }
        if (text) { e.textContent = text; }
        return e;
    }

    for (var i = 1; i <= COUNT; i++) {
        var col = el('div', 'width:' + COL_W + 'px;box-sizing:border-box;padding:6px 6px 0;' +
                            'display:flex;flex-direction:column;align-items:center;' +
                            'justify-content:flex-start;text-align:center;');
        col.appendChild(el('div', 'font-size:13px;font-weight:700;line-height:18px;white-space:nowrap;', NAME + ' #' + i));
        col.appendChild(el('div', 'font-size:10px;font-weight:600;line-height:13px;margin-top:4px;white-space:nowrap;', SUBTITLE));
        col.appendChild(el('div', 'height:16px;'));

        var item;
        if (MODE === 'led') {
            item = el('div', 'width:38px;height:38px;border-radius:50%;background:#9e9e9e;' +
                             'box-shadow:0 0 0 3px rgba(255,255,255,0.6),0 0 8px rgba(0,0,0,0.25);' +
                             'transition:background 0.3s;');
        } else {
            item = el('div', 'font-size:17px;font-weight:700;line-height:38px;white-space:nowrap;', '–');
        }
        col.appendChild(item);
        stage.appendChild(col);
        cells.push(item);
    }

    function isTrue(v) { return v === true || v === 'true' || v === 1 || v === '1'; }
    function last(s) { var d = s.data; return (d && d.length) ? d[d.length - 1][1] : undefined; }

    function update() {
        var v = {};
        (self.ctx.data || []).forEach(function (s) { v[s.dataKey.label || s.dataKey.name] = last(s); });
        var offline = (v.active !== undefined) && !isTrue(v.active);

        for (var i = 1; i <= COUNT; i++) {
            var raw = parseFloat(v[KEY + i]);
            var item = cells[i - 1];
            if (MODE === 'led') {
                var bad = offline || isNaN(raw) || raw < MIN || raw > MAX;
                item.style.background = bad ? '#e74c3c' : '#2ecc71';
            } else if (offline) {
                item.textContent = 'offline';
                item.style.color = '#e74c3c';
            } else {
                item.textContent = isNaN(raw) ? '–' : (raw / DIVISOR).toFixed(1) + UNIT;
                item.style.color = INK;
            }
        }
    }

    // scale the whole stage to fit the widget (width AND height)
    function layout() {
        var w = root.clientWidth, h = root.clientHeight;
        if (!w || !h) { return; }
        var s = Math.min(w / DESIGN_W, h / DESIGN_H);
        var x = (w - DESIGN_W * s) / 2;
        var y = (h - DESIGN_H * s) / 2;
        stage.style.transform = 'translate(' + x + 'px,' + y + 'px) scale(' + s + ')';
    }

    if (window.ResizeObserver) {
        ro = new ResizeObserver(layout);
        ro.observe(root);
    }
    self.onResize = layout;
    self.onDataUpdated = update;
    self.ctx.rsObserver = ro;
    layout();
    update();
};

self.onDestroy = function () {
    if (self.ctx.rsObserver) { self.ctx.rsObserver.disconnect(); }
};

